Mesh<Point, double> mesh;
std::vector<std::vector<Point>> faces;
std::vector<double> edge_lengths;

// Collect all edges from the regular triangulation
std::vector<std::pair<std::size_t, std::size_t>> edges;
for (std::size_t i = 0; i < rt.number_of_edges(); ++i) {
    auto edge = rt.edge(i);
    if (rt.is_infinite(edge.first) || rt.is_infinite(edge.second)) continue;
    edges.emplace_back(edge.first, edge.second);
}

// Process each edge to find incident cells (faces)
for (const auto& edge : edges) {
    std::size_t cell1 = rt.edge_cell(edge.first, edge.second);
    std::size_t cell2 = rt.edge_cell(edge.second, edge.first);

    if (cell1 == cell2) continue; // Skip edges not shared by two cells

    // Get the edge length
    Point p1 = rt.point(edge.first);
    Point p2 = rt.point(edge.second);
    double length = std::sqrt(std::pow(p1.x() - p2.x(), 2) + std::pow(p1.y() - p2.y(), 2));
    edge_lengths.push_back(length);

    // Collect vertices of the two incident cells
    std::vector<Point> vertices1, vertices2;
    for (std::size_t i = 0; i < rt.number_of_vertices_in_cell(cell1); ++i) {
        vertices1.push_back(rt.point(rt.vertex_in_cell(cell1, i)));
    }
    for (std::size_t i = 0; i < rt.number_of_vertices_in_cell(cell2); ++i) {
        vertices2.push_back(rt.point(rt.vertex_in_cell(cell2, i)));
    }

    // Find the common edge vertices in both cells
    Point common1, common2;
    for (const auto& p : vertices1) {
        if (p == p1 || p == p2) {
            if (p == p1) common1 = p;
            else common2 = p;
        }
    }

    // Construct the face polygon by merging the two cells' vertices
    std::vector<Point> face_vertices;
    face_vertices.push_back(common1);
    bool found_common2 = false;
    for (const auto& p : vertices1) {
        if (p != common1 && p != common2) face_vertices.push_back(p);
    }
    for (const auto& p : vertices2) {
        if (p != common2 && p != common1) face_vertices.push_back(p);
    }
    face_vertices.push_back(common2);

    // Ensure the face is valid (has at least 3 vertices)
    if (face_vertices.size() >= 3) {
        faces.push_back(face_vertices);
    }
}

// Create the mesh with faces and edge lengths
mesh.faces = std::move(faces);
mesh.edge_lengths = std::move(edge_lengths);
// END_CODE

